'use strict';

// MODULES //

var cartesianProduct = require( '@stdlib/array/cartesian-product' );
var promotionRules = require( '@stdlib/ndarray/promotion-rules' );
var dtypeChar = require( '@stdlib/ndarray/base/dtype-char' );
var dtypes = require( '@stdlib/ndarray/dtypes' );
var format = require( '@stdlib/string/format' );
var safeCasts = require( '@stdlib/ndarray/safe-casts' );
var generateTable = require( './table.js' );
var config = require( './config.js' );


// FUNCTIONS //

/**
* Returns an array of matches with valid combinations.
*
* @private
* @param {Array} matches - array of all combinations
* @returns {Array} array of matches with valid combinations
*/
function getValidCombinations( matches ) {
	var validMatches = [];
	var validDtypes;
	var i;

	for ( i = 0; i < matches.length; i++ ) {
		// Skip complex32, float16, uint8c and int16 as we don't support them yet...
		if ( matches[ i ][ 0 ] === 'complex32' ||
			matches[ i ][ 0 ] === 'int16' ||
			matches[ i ][ 0 ] === 'float16' ||
			matches[ i ][ 0 ] === 'uint8c' ||
			matches[ i ][ 1 ] === 'complex32' ||
			matches[ i ][ 1 ] === 'int16'||
			matches[ i ][ 1 ] === 'float16' ||
			matches[ i ][ 1 ] === 'uint8c' ) {
			continue;
		}

		// Check if the dtypes are valid for the current match...
		validDtypes = safeCasts( matches[ i ][ 5 ] );
		if ( validDtypes && validDtypes.includes( matches[ i ][ 1 ] ) && promotionRules( matches[ i ][ 0 ], matches[ i ][ 1 ] ) === matches[ i ][ 4 ] ) { // eslint-disable-line max-len
			validMatches.push( matches[ i ] );
		}
	}

	return validMatches;
}


// MAIN //

/**
* Generate dtype pairs, match them with appropriate packages, and resolve C function names and loop kernels.
*
* ## Note
*
* -   The function generates an array of matches, where each match is an array of the following format:
*
* ```text
*             ----------------------------------------------------------------------------------------------------------------------------------------
*  Array:    | input_dtype | output_dtype | package | needs_to_promote | promoted_input_dtype | promoted_output_dtype | c_function_name | loop_kernel |
*             ----------------------------------------------------------------------------------------------------------------------------------------
*                   |              |           |            |                     |                      |                      |              |
*                   |              |           |            |                     |                      |                      |              |
*                   V              V           |            V                     V                      V                      |              V
*  Example:     'float32'       'float32'      |           true               'float64'              'float64'                  |       'stdlib_ndarray_d_d'
*                                              V                                                                                V
*                               '@stdlib/math/base/special/expf'                                                         'stdlib_base_expf'
* ```
*
* @private
* @returns {Array} matches table containing dtype pairs and their corresponding package information
*/
function main() {
	var cFuncName;
	var matches = [];
	var kernel;
	var table;
	var pairs;
	var pdt;
	var row;
	var idt;
	var odt;
	var dt;
	var i;
	var j;

	/*
		Generate the table. For example, we'll have:
		Table: [
			[ 'float32', 'float32', '@stdlib/math/base/special/ceilf' ],
			[ 'float64', 'float64', '@stdlib/math/base/special/ceil' ],
			[ 'complex64', 'complex64', '@stdlib/math/base/special/cceilf' ]
			[ 'complex128', 'complex128', '@stdlib/math/base/special/cceil' ],
		]
	*/
	table = generateTable();

	/*
		Resolve list of input dtypes. For example, we'll have:
		idt = [
			'complex32',
			'complex64',
			'complex128',
			'float16',
			'float32',
			'float64',
			'int32',
			'int16',
			'int8',
			'uint32',
			'uint16',
			'uint8',
			'uint8c'
		]
	*/
	idt = dtypes( config.input_dtypes );

	/*
		Resolve the list of output dtypes. For example, we'll have:
		odt = [
			'complex32',
			'complex128',
			'complex64',
			'float16',
			'float64',
			'float32',
			'int32',
			'int16',
			'int8',
			'uint32',
			'uint16',
			'uint8',
			'uint8c'
		]
	*/
	odt = dtypes( config.output_dtypes );

	/*
		Generate the input-output dtype pairs. For example, we'll have:
		pairs = [
			[ 'complex32', 'complex32' ],
			[ 'complex32', 'complex64' ],
			[ 'complex32', 'complex128' ],
			[ 'complex32', 'float16' ],
			[ 'complex32', 'float32' ],
			[ 'complex32', 'float64' ],
			[ 'complex32', 'int32' ],
			[ 'complex32', 'int16' ],
			[ 'complex32', 'int8' ],
			[ 'complex32', 'uint32' ],
			[ 'complex32', 'uint16' ],
			[ 'complex32', 'uint8' ],
			[ 'complex32', 'uint8c' ],
			[ 'complex64', 'complex32' ],
			[ 'complex64', 'complex64' ],
			[ 'complex64', 'complex128' ],
			[ 'complex64', 'float16' ],
			[ 'complex64', 'float32' ],
			[ 'complex64', 'float64' ],
			[ 'complex64', 'int32' ],
			...
		]
	*/
	pairs = cartesianProduct( idt, odt );

	// Match-make each dtype pair with a stdlib package...
	for ( i = 0; i < pairs.length; i++ ) {
		// Now let dt = [ 'uint32', 'float32' ]...
		dt = pairs[ i ];

		for ( j = 0; j < table.length; j++ ) {
			row = table[ j ];

			// Resolve the scalar math kernel C function name from package path ( e.g., '@stdlib/math/base/special/ceilf' -> 'ceilf' --> 'stdlib_base_ceilf' ):
			cFuncName = 'stdlib_base_' + row[ 2 ].split( '/' ).pop();

			// Firstly, look for exact matches. For example, let row = [ 'float32', 'float32', '@stdlib/math/base/special/ceilf' ]...
			if ( row[ 0 ] === dt[ 0 ] && row[ 1 ] === dt[ 1 ] ) {
				// Resolve the loop kernel...
				kernel = format( 'stdlib_ndarray_%s_%s', dtypeChar( row[ 0 ] ), dtypeChar( row[ 1 ] ) );
				matches.push( [ dt[ 0 ], dt[ 1 ], row[ 2 ], false, null, null, cFuncName, kernel ] ); // eslint-disable-line max-len
				break;
			}

			// Then check for package to which the dtype pair can promote. For example, pdt = promotionRules( 'uint32', 'float32' ) = 'float64':
			pdt = promotionRules( dt[ 0 ], row[ 0 ] );
			if ( pdt ) {
				// Check if the package in the present row supports the promoted dtypes...
				if ( row[ 0 ] === pdt && row[ 1 ] === pdt ) {
					// Resolve the loop kernel...
					kernel = format( 'stdlib_ndarray_%s_%s_as_%s_%s', dtypeChar( dt[ 0 ] ), dtypeChar( dt[ 1 ] ), dtypeChar( row[ 0 ] ), dtypeChar( row[ 1 ] ) );
					matches.push( [ dt[ 0 ], dt[ 1 ], row[ 2 ], true, pdt, pdt, cFuncName, kernel ] ); // eslint-disable-line max-len
				}
			}
		}
	}

	return getValidCombinations( matches );
}

module.exports = main;
